public static class V7Tests {
 static void Check(bool value,string reason){if(!value)throw new Exception(reason);}
 static void Layout(FrameworkElement view,double width=720,double height=260){view.Measure(new Size(width,height));view.Arrange(new Rect(0,0,width,height));view.UpdateLayout();}
 static IEnumerable<T> Children<T>(DependencyObject root) where T:DependencyObject {for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);if(child is T)yield return (T)child;foreach(var nested in Children<T>(child))yield return nested;}}
 public static int Run(string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);var log=new List<string>();var app=Application.Current??new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};
 var m=new Metrics();m.Gpus.Add(new Gpu{Index="0",Uuid="gpu0",Fan="[N/A]",Cap="[N/A]"});m.Gpus.Add(new Gpu{Index="1",Uuid="gpu1",Cap="200"});LocalGpu.ApplyPowerXml(m,"<?xml version='1.0'?><!DOCTYPE nvidia_smi_log SYSTEM 'nvsmi_device_v12.dtd'><nvidia_smi_log><gpu><uuid>gpu0</uuid><gpu_power_readings><current_power_limit>78.50 W</current_power_limit><default_power_limit>50 W</default_power_limit><max_power_limit>115 W</max_power_limit></gpu_power_readings><fan_speed>N/A</fan_speed></gpu><gpu><uuid>other</uuid><gpu_power_readings><current_power_limit>999 W</current_power_limit></gpu_power_readings></gpu></nvidia_smi_log>");Check(m.Gpus[0].Cap=="78.50"&&m.Gpus[0].PowerMax=="115"&&m.Gpus[1].Cap=="200","current/max power are distinct and UUID matched");Check(GpuTelemetry.Unit(m.Gpus[0].Fan,"%") == "未提供"&&GpuTelemetry.Memory("[N/A] MiB")=="未提供","missing driver fields are not zero");log.Add("POWER_CURRENT_MAX_UUID_MATCH_AND_UNAVAILABLE_FIELDS=True");
 var adapters=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{"luid_0x00000000_0x00000001_phys_0","0"},{"luid_0x00000000_0x00000002_phys_0","1"},{"luid_0x00000000_0x00000001_phys_1","1"}};m.Processes.Add(new GpuProcess{Gpu="0",Pid="10",Name="[Insufficient Permissions]",Memory="[N/A] MiB"});m.Processes.Add(new GpuProcess{Gpu="1",Pid="10",Memory="77 MiB"});LocalGpu.ApplyCounters(m,adapters,new[]{new GpuMemoryCounter{Name="pid_10_luid_0x00000000_0x00000001_phys_0",Dedicated=25*1048576,Shared=3*1048576},new GpuMemoryCounter{Name="pid_10_luid_0x00000000_0x00000002_phys_0",Dedicated=99*1048576},new GpuMemoryCounter{Name="pid_11_luid_0x00000000_0x00000003_phys_0",Dedicated=888*1048576},new GpuMemoryCounter{Name="pid_12_luid_0x00000000_0x00000001_phys_0",Dedicated=2*1048576},new GpuMemoryCounter{Name="pid_12_luid_0x00000000_0x00000001_phys_1",Dedicated=3*1048576}},pid=>"test"+pid,pid=>"user");Check(m.Processes[0].Memory=="25.0 MiB"&&m.Processes[0].SharedMemory=="3.0 MiB"&&m.Processes[0].Name=="test10","dedicated/shared and process name fallback");Check(m.Processes[1].Memory=="77 MiB"&&!m.Processes.Any(x=>x.Pid=="11")&&m.Processes.Single(x=>x.Pid=="12"&&x.Gpu=="0").Memory=="2.0 MiB"&&m.Processes.Single(x=>x.Pid=="12"&&x.Gpu=="1").Memory=="3.0 MiB","cross GPU/PID mapping, physical-node isolation, NVIDIA read retained");log.Add("PER_PROCESS_MEMORY_MULTI_ADAPTER_PID_MAPPING_AND_SHARED_SEPARATION=True");var json=ArchiveStore.Json().Serialize(ArchiveRecord.From(m,DateTime.UtcNow,5));var restored=ArchiveStore.Json().Deserialize<ArchiveRecord>(json).Metrics();Check(restored.Gpus[0].PowerMax=="115"&&restored.Processes[0].SharedMemory=="3.0 MiB","new details retained in archive");log.Add("EXTENDED_TELEMETRY_ARCHIVE_ROUNDTRIP=True");
 long from=DateTime.UtcNow.AddMinutes(-2).Ticks,to=from+TimeSpan.FromMinutes(2).Ticks;var points=new List<ArchivePoint>();for(int i=0;i<25;i++)points.Add(new ArchivePoint{T=from+TimeSpan.FromSeconds(i*5).Ticks,Cpu=i,Memory=i+20,Gpu=i+40,GpuIds=new[]{"0","1"},GpuUsage=new[]{i+10.0,i+30.0},Interval=5});var history=new HistoryChart{From=from,To=to,HoverPoints=points};Layout(history);foreach(string metric in new[]{"CPU","内存","GPU","GPU 0","GPU 1"}){history.Metric=metric;long tick=points[8].T;double x=48+(history.ActualWidth-64)*(tick-from)/(double)(to-from);history.HoverAt(new Point(x,80));Check(history.HoverReading!=null&&history.HoverReading.SampleUtc.Ticks==tick&&!history.HoverReading.Gap&&history.HoverReading.Value==points[8].Value(metric),"exact hover for "+metric);Check(history.HoverText.Contains(metric)&&history.HoverText.Contains("实际采样"),"time and metric hover text");}log.Add("ALL_HISTORY_METRICS_USE_ORIGINAL_SAMPLES_FOR_HOVER=True");history.Data=new List<ArchiveDot>{new ArchiveDot{T=from,Value=0},new ArchiveDot{T=to,Value=24}};history.Metric="CPU";history.HoverAt(new Point(48+(history.ActualWidth-64)*40/120.0,80));Check(history.HoverReading.Value==8,"hover not taken from downsampled endpoints");points[8].Error="offline";history.HoverAt(new Point(48+(history.ActualWidth-64)*40/120.0,80));Check(history.HoverReading.Gap&&history.HoverText.Contains("offline"),"failed sample hover");history.HoverPoints=new List<ArchivePoint>{points[0],points[24]};history.HoverAt(new Point(48+(history.ActualWidth-64)/2,80));Check(history.HoverReading.Gap&&history.HoverText.Contains("无有效采样"),"gap not interpolated");history.HoverAt(new Point(-1,20));Check(history.HoverReading==null,"outside chart hover");history.ClearHover();Check(history.HoverText=="","mouse leave resets hover");log.Add("HOVER_DOWNSAMPLING_GAPS_FAILURES_AND_MOUSE_LEAVE=True");
 var live=new TrendChart{Data=new List<ResourceSample>{new ResourceSample{Time=DateTime.UtcNow.AddSeconds(-5),Cpu=33.3,Memory=44.4}},Interval=5};Layout(live);foreach(bool memory in new[]{false,true}){live.Memory=memory;live.HoverAt(new Point(48+(live.ActualWidth-60)*295/300.0,60));Check(live.HoverReading!=null&&!live.HoverReading.Gap&&live.HoverReading.Value==(memory?44.4:33.3),"live hover CPU and memory");}live.HoverAt(new Point(60,80));Check(live.HoverReading.Gap,"live missing history is not fabricated");log.Add("LIVE_CPU_MEMORY_TIME_VALUE_AND_GAP_HOVER=True");
 var window=new MonitorWindow(true);window.SetMetrics(Program.Fixture("eight"));window.SwitchView("GPU");window.RenderImage(Path.Combine(folder,"gpu-0-through-7.png"),1200,1000,120);Check(window.CardViews[0].Id.Text=="GPU 0"&&window.CardViews[7].Id.Text=="GPU 7","plain GPU indices");var card=window.CardViews[0];var update=Program.Fixture("eight");update.Gpus[0].Util="46";window.SetMetrics(update);Check(object.ReferenceEquals(card,window.CardViews[0])&&card.Meter.Value==46&&card.Percent.Text=="46%","updating GPU meters reused with immediate measured value");Check(window.Audit().Count==0,"GPU layout has no overlaps");log.Add("GPU_INDICES_AND_STABLE_CARD_UPDATES=True");
 window.SwitchView("CPU");Check(!window.CoresExpanded,"core panel initially collapsed");for(int i=0;i<4;i++){window.ShowCores();Check(window.CoresExpanded==((i%2)==0),"core toggle "+i);window.SetMetrics(Program.Fixture("eight"));Check(window.CoresExpanded==((i%2)==0),"polling keeps core toggle state");}window.ShowCores();window.SwitchView("GPU");window.SwitchView("CPU");Check(window.CoresExpanded,"core toggle preserved through tab switch");window.ShowCores();Check(!window.CoresExpanded,"can collapse after tab switch");window.RenderImage(Path.Combine(folder,"cpu-collapsed.png"),1100,800,120);window.ShowCores();window.RenderImage(Path.Combine(folder,"cpu-expanded.png"),1100,800,120);log.Add("REPEATED_CORE_TOGGLE_WITH_POLL_AND_TAB_STATE=True");
 int renders=0;foreach(string theme in Theme.Keys){window.ApplyAppearance(theme);window.SwitchView("GPU");window.SetMetrics(Program.Fixture("eight"));foreach(var size in new[]{new[]{760,560},new[]{1200,1000}}){window.RenderImage(Path.Combine(folder,theme+"-"+size[0]+".png"),size[0],size[1],120);Check(window.Audit().Count==0,"theme metric layout "+theme+size[0]);renders++;}}window.Exit();log.Add("NEW_LAYOUT_THEME_SIZE_RENDERS="+renders);File.WriteAllLines(Path.Combine(folder,"v7-results.txt"),log);Console.WriteLine(string.Join("\n",log));return 0;}

 static void Shot(MonitorWindow window,string path){Motion.Complete(window.Body);window.UpdateLayout();window.RenderImage(path,(int)Math.Ceiling(window.Root.ActualWidth+48),(int)Math.Ceiling(window.Root.ActualHeight+48),120);}
 public static void Runtime(Application app,string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);Storage.PathName=Path.Combine(folder,"settings.xml");ArchiveStore.DefaultRoot=Path.Combine(folder,"archives");var local=Storage.LocalServer();var remote=Storage.DefaultServer();var options=new Settings{Interval=3,SelectedName=local.Name,SelectedView="GPU"};options.Servers.Add(remote);options.Servers.Add(local);Storage.Save(options);var window=new MonitorWindow(false){SilentTrayTransitions=true,ShowActivated=false,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.Manual,Left=-18000,Top=-18000};app.MainWindow=window;window.Show();DateTime begin=DateTime.UtcNow.AddSeconds(-1);var watch=System.Diagnostics.Stopwatch.StartNew();var log=new List<string>();window.IsVisibleChanged+=(s,e)=>log.Add("WINDOW_VISIBLE="+window.IsVisible+" T="+watch.Elapsed.TotalSeconds.ToString("0.00"));window.ServerPicker.SelectionChanged+=(s,e)=>log.Add("DEVICE="+((window.ServerPicker.SelectedItem as Server)==null?"none":((Server)window.ServerPicker.SelectedItem).Name)+" T="+watch.Elapsed.TotalSeconds.ToString("0.00"));var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(200)};int phase=0,baseline=0,trayRemote=0,trayLocal=0;DateTime animationAt=DateTime.MinValue;Window host=null;Grid animationRoot=null;PixelMeter meter=null;GpuCard stable=null;FrameworkElement stableCore=null;
 timer.Tick+=(sender,e)=>{try{Check(watch.Elapsed.TotalSeconds<100,"runtime timeout phase "+phase);var store=window.ArchiveRepository;var lr=store.Query(local,begin,DateTime.UtcNow.AddSeconds(1),CancellationToken.None);var rr=store.Query(remote,begin,DateTime.UtcNow.AddSeconds(1),CancellationToken.None);
 if(phase==0&&lr.Points.Count>=2&&rr.Points.Count>=2){var localMetrics=store.Read(lr.Points.Last()).Metrics();Check(localMetrics.Gpus.Count==1&&string.IsNullOrEmpty(localMetrics.Error),"actual local GPU");var gpu=localMetrics.Gpus[0];Check(GpuTelemetry.Available(gpu.Cap)&&GpuTelemetry.Available(gpu.PowerMax),"actual power cap/max available");Check(localMetrics.Processes.Any(x=>(x.MemorySource??"").Contains("WDDM")&&GpuTelemetry.Memory(x.Memory)!="未提供"),"actual process memory fallback");Check(window.CardViews[0].Id.Text=="GPU 0","actual plain GPU index");log.Add("LIVE_CURRENT_POWER_LIMIT_W="+gpu.Cap);log.Add("LIVE_MAX_POWER_LIMIT_W="+gpu.PowerMax);log.Add("LIVE_FAN="+GpuTelemetry.Unit(gpu.Fan,"%"));log.Add("LIVE_PROCESS_MEMORY_ROWS="+localMetrics.Processes.Count(x=>(x.MemorySource??"").Contains("WDDM")));log.Add("LOCAL_AND_REMOTE_CAPTURE_CONTINUE=True");Shot(window,Path.Combine(folder,"local-gpu-live.png"));window.Scroll.ScrollToBottom();Shot(window,Path.Combine(folder,"local-processes-live.png"));animationRoot=new Grid{Background=Theme.Bg,Margin=new Thickness(24)};meter=new PixelMeter(10,Theme.Green,12){VerticalAlignment=VerticalAlignment.Center};animationRoot.Children.Add(meter);host=new Window{Title="AQServer animation diagnostic",Width=480,Height=140,ShowActivated=false,Content=animationRoot,Background=Theme.Bg};host.Show();phase=1;}
 else if(phase==1){Check(meter.IsLoaded&&meter.IsVisible,"animated meter loaded");if(SystemParameters.ClientAreaAnimation){meter.Value=80;Check(meter.IsAnimating,"animation started");meter.Advance(140);Check(meter.DisplayValue>10&&meter.DisplayValue<80&&meter.TrailValue>10&&meter.TrailValue<meter.DisplayValue,"nonlinear rising fill and delayed trail");Snapshot.Save(animationRoot,Path.Combine(folder,"animation-rise-synthetic.png"),440,100,120,null);meter.Advance(690);Check(meter.Value==80&&meter.DisplayValue==80&&!meter.IsAnimating,"animation completes exactly");meter.Value=20;meter.Advance(140);Check(meter.DisplayValue>20&&meter.DisplayValue<80&&meter.TrailValue>meter.DisplayValue&&meter.TrailValue<80,"nonlinear falling fill and delayed afterimage");Snapshot.Save(animationRoot,Path.Combine(folder,"animation-fall-synthetic.png"),440,100,120,null);meter.Advance(690);meter.Value=60;animationAt=DateTime.UtcNow;log.Add("NONLINEAR_DAMPED_FILL_AND_TRAIL_RISE_FALL=True");}else{meter.Value=60;animationAt=DateTime.UtcNow;log.Add("WINDOWS_REDUCED_MOTION_RESPECTED=True");}phase=2;}
 else if(phase==2&&(DateTime.UtcNow-animationAt).TotalSeconds>0.8){Check(!meter.IsAnimating&&meter.DisplayValue==60,"real animation timer completes");meter.Value=25;host.Close();Check(!meter.IsAnimating,"unload stops animation timer");log.Add("ANIMATION_TIMER_COMPLETION_AND_UNLOAD=True");window.SwitchView("CPU");window.ShowCores();Check(window.CoresExpanded,"core panel expands");window.ShowCores();Check(!window.CoresExpanded,"core panel collapses");window.ShowCores();window.UpdateLayout();stableCore=Children<WrapPanel>(window.Body).Last().Children[0] as FrameworkElement;baseline=lr.Points.Count;phase=3;}
 else if(phase==3&&lr.Points.Count>baseline){Check(window.CoresExpanded,"poll preserves expanded panel");Check(object.ReferenceEquals(stableCore,Children<WrapPanel>(window.Body).Last().Children[0]),"core cells reused across poll");Shot(window,Path.Combine(folder,"local-cores-live.png"));window.ShowCores();Check(!window.CoresExpanded,"collapse after poll");window.UpdateLayout();var live=Children<TrendChart>(window.Body).Single();Check(live.MotionFrames>0||!Motion.Enabled,"real sample chart arrival animation");var sample=window.History.Last();double age=(DateTime.UtcNow-sample.Time).TotalSeconds;live.HoverAt(new Point(48+(live.ActualWidth-60)*(1-age/300),live.ActualHeight/2));Check(live.HoverText.Contains("CPU")&&live.HoverText.Contains("实际采样"),"actual CPU hover");Check(!live.IsChartAnimating,"hover freezes chart motion");log.Add("CHART_NEW_SAMPLE_NONLINEAR_ARRIVAL_AND_HOVER_STABILITY=True");Shot(window,Path.Combine(folder,"local-cpu-hover-live.png"));window.SwitchView("内存");window.UpdateLayout();live=Children<TrendChart>(window.Body).Single();age=(DateTime.UtcNow-window.History.Last().Time).TotalSeconds;live.HoverAt(new Point(48+(live.ActualWidth-60)*(1-age/300),live.ActualHeight/2));Check(live.HoverText.Contains("内存"),"actual memory hover");Shot(window,Path.Combine(folder,"local-memory-hover-live.png"));log.Add("REPEATED_CORE_BUTTON_AND_STABLE_CORE_CELLS=True");log.Add("LIVE_CPU_MEMORY_HOVER_TIME_AND_VALUE=True");window.SwitchView("GPU");stable=window.CardViews[0];baseline=lr.Points.Count;phase=4;}
 else if(phase==4&&lr.Points.Count>baseline){Check(object.ReferenceEquals(stable,window.CardViews[0]),"GPU card retained during actual polling");Check(window.Audit().Count==0,"native GPU no overlapping labels");log.Add("LIVE_GPU_CARD_REUSE_FOR_ANIMATION=True");window.SwitchView("历史");window.ArchiveView.SetRange(begin,DateTime.UtcNow.AddSeconds(1),true);phase=5;}
 else if(phase==5&&!window.ArchiveView.Loading&&window.ArchiveView.CurrentResult!=null){var panel=window.ArchiveView;window.UpdateLayout();window.Scroll.ScrollToVerticalOffset(((FrameworkElement)panel.Children[0]).ActualHeight+16);window.UpdateLayout();panel.SetMetric("GPU 0");var chart=panel.Chart;var result=panel.CurrentResult;var point=result.Points[result.Points.Count/2];chart.HoverAt(new Point(48+(chart.ActualWidth-64)*(point.T-chart.From)/(double)(chart.To-chart.From),chart.ActualHeight/2));Check(chart.HoverReading!=null&&!chart.HoverReading.Gap&&chart.HoverText.Contains("GPU 0"),"actual history hover");Shot(window,Path.Combine(folder,"local-history-hover-live.png"));log.Add("LIVE_HISTORY_GPU_HOVER_ORIGINAL_SNAPSHOT=True");trayRemote=rr.Points.Count;trayLocal=lr.Points.Count;window.HideToTray();phase=6;}
 else if(phase==6&&lr.Points.Count>=trayLocal+2&&rr.Points.Count>=trayRemote+2){Check(!window.IsVisible&&window.TrayVisible,"tray continues collection: visible="+window.IsVisible+" tray="+window.TrayVisible);log.Add("TRAY_BOTH_DEVICES_CONTINUE_ARCHIVING=True");window.CompactOptions.MiniLeft=-18000;window.CompactOptions.MiniTop=-18000;window.ShowCompact();window.CompactView.Left=-18000;window.CompactView.Top=-18000;Check(window.CompactView.IsVisible&&!window.IsVisible&&window.CompactView.Topmost,"native compact topmost");window.CompactView.DevicePicker.SelectedItem=window.CompactDevices.First(x=>!x.IsLocal);Check(window.CompactView.GpuCount==8,"compact remote eight GPU cached readings");trayRemote=rr.Points.Count;trayLocal=lr.Points.Count;phase=7;}
 else if(phase==7&&lr.Points.Count>=trayLocal+2&&rr.Points.Count>=trayRemote+2){Check(window.CompactView.GpuCount==8&&window.CompactView.CpuText==window.CompactMetrics.Cpu,"compact follows live capture");CompactTests.Shot(window.CompactView,Path.Combine(folder,"remote-compact-live.png"));Check(window.BackgroundDeviceCount==2,"compact does not add collectors");log.Add("COMPACT_LIVE_REMOTE_8_GPU_LOCAL_UNSELECTED_ARCHIVE_AND_NO_EXTRA_COLLECTOR=True");window.Restore();Check(!window.CompactView.IsVisible&&window.IsVisible,"native expand to main");log.Add(window.NativeReview());log.Add("STARTUP_NOT_MODIFIED=True");timer.Stop();window.Exit();var reopened=new ArchiveStore(ArchiveStore.DefaultRoot);Check(reopened.Query(local,begin,DateTime.UtcNow.AddSeconds(1),CancellationToken.None).Points.Count>=lr.Points.Count,"archive exit flush");File.WriteAllLines(Path.Combine(folder,"runtime-results.txt"),log);}
 }catch(Exception error){timer.Stop();if(host!=null)host.Close();File.WriteAllLines(Path.Combine(folder,"runtime-trace.txt"),log);File.WriteAllText(Path.Combine(folder,"runtime-error.txt"),error.ToString());window.Exit();}};timer.Start();}
